// ===== Begin: toolboxes/core/gpu/cuNDArray_blas.h =====
/** \file cuNDArray_blas.h
    \brief BLAS level-1 functions on the cuNDArray class.
    
    cuNDArray_blas.h provides BLAS level-1 functions on the cuNDArray class.
    The cuNDArray is temporarily reshaped to a column vector for the respective operations.
    The implementation is based on CUBLAS.
    This code is purposely split into a header and underlying implementation (.cpp) 
    as this allows specific instantiation of the supported template types.     
    The supported types are float, double, std::complex<float>, std::complex<double>, 
    Gadgetron::complext<float>, and Gadgetron::complext<double>.
*/





namespace Gadgetron{

    /**
   * @brief compute dot product of two vectors
   * @param x Input data
   * @param y Input data
   * @param batchSize Size of each batch of the data that is processed on the GPU at a time 
   * @param cc complex conjugate. calculate dot product of conj(x) and y if cc = true else x.y
   * @return x.y
   */

  template<class T> T dot( cuNDArray<T> *x, cuNDArray<T> *y, size_t batchSize = INT_MAX, bool cc = true );

  
  /**
   * @brief compute ||x||
   * @param x Input data
   * @param batchSize Size of each batch of the data that is processed on the GPU at a time 
   * @return Euclidean norm of x
   */

  template<class T> typename realType<T>::Type nrm2( cuNDArray<T> *x , size_t batchSize = INT_MAX);

    /**
   * @brief Compute  y = ax + y
   * @param a scalar a
   * @param x Input data
   * @param y Input data that will be updated
   * @param batchSize Size of each batch of the data that is processed on the GPU at a time
   */

  template<class T> void axpy( T a, cuNDArray<T>* x, cuNDArray<T>* y , size_t batchSize = INT_MAX);

  template<class T> void axpy( T a, cuNDArray<complext<T> > *x, cuNDArray<complext<T> > *y , size_t batchSize = INT_MAX);
  
  /**
   * @brief Gets the index of the index of the element with minimum absolute
   * @param x Input data
   * @param batchSize Size of each batch of the data that is processed on the GPU at a time 
   * @return index of absolute minimum values
   * @details Note that this returns the C-style index and NOT the Fortran index.
   */

  template<class T> size_t amin( cuNDArray<T> *x , size_t batchSize = INT_MAX);

  /**
   * @brief Gets the index of the index of the element with maximum absolute
   * @param x Input data
   * @param batchSize Size of each batch of the data that is processed on the GPU at a time
   * @return index of absolute maximum values
   * @details Note that this returns the C-style index and NOT the Fortran index.
   */

  template<class T> size_t amax( cuNDArray<T> *x , size_t batchSize = INT_MAX);

  /**
   * @brief Compute the sum of absolute values of the elements of vector x
   * @param x Input data
   * @param batchSize Size of each batch of the data that is processed on the GPU at a time
   * @return absolute value sum of the input vector
   */
  
  template<class T> typename realType<T>::Type asum( cuNDArray<T> *x , size_t batchSize = INT_MAX );

/* DPCT_ORIG   std::string gadgetron_getCublasErrorString(cublasStatus_t err);*/
  std::string gadgetron_getCublasErrorString(int err);
}
// ===== End: toolboxes/core/gpu/cuNDArray_blas.h =====



using namespace Gadgetron;
using testing::Types;

template <typename T> class cuNDArray_blas_Real : public ::testing::Test 
{
protected:
  virtual void SetUp() {
    size_t vdims[] = {37, 49, 23, 19}; //Using prime numbers for setup because they are messy
    dims = std::vector<size_t>(vdims,vdims+sizeof(vdims)/sizeof(size_t));
    Array = cuNDArray<T>(dims);
    Array2 = cuNDArray<T>(dims);
  }
  std::vector<size_t> dims;
  cuNDArray<T> Array;
  cuNDArray<T> Array2;
};

typedef Types<float, double> realImplementations_cuNDArray_blas_test;

TYPED_TEST_SUITE(cuNDArray_blas_Real, realImplementations_cuNDArray_blas_test);

TYPED_TEST(cuNDArray_blas_Real,dotTest){
  fill(&this->Array,TypeParam(1));
  EXPECT_FLOAT_EQ(this->Array.get_number_of_elements(),real(dot(&this->Array,&this->Array)));
  fill(&this->Array2,TypeParam(2));
  EXPECT_FLOAT_EQ(this->Array.get_number_of_elements()*2,real(dot(&this->Array,&this->Array2)));

  EXPECT_FLOAT_EQ(this->Array.get_number_of_elements() * 2, real(dot(&this->Array, &this->Array2, 16)));
  EXPECT_FLOAT_EQ(this->Array.get_number_of_elements() * 2, real(dot(&this->Array, &this->Array2, 17)));
}

TYPED_TEST(cuNDArray_blas_Real,axpyTest){
  fill(&this->Array,TypeParam(71));
  fill(&this->Array2,TypeParam(97));
  axpy(TypeParam(11),&this->Array,&this->Array2);
  TypeParam val = this->Array2[10];
  EXPECT_FLOAT_EQ(878,real(val));

  fill(&this->Array2, TypeParam(97));
  axpy(TypeParam(11), &this->Array, &this->Array2 ,16);
  val = this->Array2[10];
  EXPECT_FLOAT_EQ(878, real(val));

  fill(&this->Array2, TypeParam(97));
  axpy(TypeParam(11), &this->Array, &this->Array2 ,17);
  val = this->Array2[10];
  EXPECT_FLOAT_EQ(878, real(val));
}

TYPED_TEST(cuNDArray_blas_Real,nrm2Test){
  fill(&this->Array,TypeParam(1));
  EXPECT_FLOAT_EQ(std::sqrt((double)this->Array.get_number_of_elements()),nrm2(&this->Array));
  fill(&this->Array,TypeParam(3));
  EXPECT_FLOAT_EQ(std::sqrt(3.0*3.0*this->Array.get_number_of_elements()),nrm2(&this->Array));

  // Some errors from the sum
  EXPECT_NEAR(std::sqrt(3.0 * 3.0 * this->Array.get_number_of_elements()), nrm2(&this->Array, 16),0.1);
  EXPECT_NEAR(std::sqrt(3.0 * 3.0 * this->Array.get_number_of_elements()), nrm2(&this->Array, 17),0.1);
}

TYPED_TEST(cuNDArray_blas_Real,asumTest){
  fill(&this->Array, TypeParam(1));
  EXPECT_FLOAT_EQ(this->Array.get_number_of_elements(), real(asum(&this->Array)));
  fill(&this->Array, TypeParam(-3));
  EXPECT_FLOAT_EQ(this->Array.get_number_of_elements() * 3, real(asum(&this->Array)));
  EXPECT_FLOAT_EQ(this->Array.get_number_of_elements() * 3, real(asum(&this->Array,16)));
  EXPECT_FLOAT_EQ(this->Array.get_number_of_elements() * 3, real(asum(&this->Array,17)));
}

TYPED_TEST(cuNDArray_blas_Real,aminTest){
  fill(&this->Array, TypeParam(100));
  TypeParam tmp(-50);
/* DPCT_ORIG   CUDA_CALL(cudaMemcpy(&this->Array.get_data_ptr()[4], &tmp, sizeof(TypeParam), cudaMemcpyHostToDevice));*/
  CUDA_CALL(DPCT_CHECK_ERROR(
      dpct::get_in_order_queue().memcpy(&this->Array.get_data_ptr()[4], &tmp, sizeof(TypeParam)).wait()));
  EXPECT_EQ(4, amin(&this->Array));
  EXPECT_EQ(4, amin(&this->Array,16));
  EXPECT_EQ(4, amin(&this->Array,17));

  tmp = TypeParam(2);
/* DPCT_ORIG   CUDA_CALL(cudaMemcpy(&this->Array.get_data_ptr()[48], &tmp, sizeof(TypeParam),
 * cudaMemcpyHostToDevice));*/
  CUDA_CALL(DPCT_CHECK_ERROR(
      dpct::get_in_order_queue().memcpy(&this->Array.get_data_ptr()[48], &tmp, sizeof(TypeParam)).wait()));
  EXPECT_EQ(48, amin(&this->Array));
  EXPECT_EQ(48, amin(&this->Array,16));
  EXPECT_EQ(48, amin(&this->Array,17));
}

TYPED_TEST(cuNDArray_blas_Real,amaxTest){
  fill(&this->Array, TypeParam(1));
  TypeParam tmp(2);
/* DPCT_ORIG   CUDA_CALL(cudaMemcpy(&this->Array.get_data_ptr()[4], &tmp, sizeof(TypeParam), cudaMemcpyHostToDevice));*/
  CUDA_CALL(DPCT_CHECK_ERROR(
      dpct::get_in_order_queue().memcpy(&this->Array.get_data_ptr()[4], &tmp, sizeof(TypeParam)).wait()));
  EXPECT_EQ(4, amax(&this->Array));
  EXPECT_EQ(4, amax(&this->Array,16));
  EXPECT_EQ(4, amax(&this->Array,17));

  tmp = TypeParam(50);
/* DPCT_ORIG   CUDA_CALL(cudaMemcpy(&this->Array.get_data_ptr()[48], &tmp, sizeof(TypeParam),
 * cudaMemcpyHostToDevice));*/
  CUDA_CALL(DPCT_CHECK_ERROR(
      dpct::get_in_order_queue().memcpy(&this->Array.get_data_ptr()[48], &tmp, sizeof(TypeParam)).wait()));
  EXPECT_EQ(48, amax(&this->Array));
  EXPECT_EQ(48, amax(&this->Array,16));
  EXPECT_EQ(48, amax(&this->Array,17));
}


