              + (this->axis_[4][8] * sp 
              + this->axis_[5][8] * sr) 
              + (this->axis_[6][8] * sa 
              + this->axis_[7][8] * sq) 
              + (this->axis_[8][8] * su 
              + this->origin_[8]);
