    template <typename T> 
    void export_3d_image(const hoNDImage<T,3>& a, const std::string& filename)
    {
        export_image(a, filename);
    }

    template <typename T> 
    void import_3d_image(hoNDImage<T,3>& a, const std::string& filename)
    {
        import_image(a, filename);
    }

