/** \file GadgetronTimer.h
    \brief Generic timer class to measure runtime performance.
*/

#ifndef __GADGETRONTIMER_H
#define __GADGETRONTIMER_H


#ifdef WIN32 
#include <windows.h>
#else 
#include <sys/time.h>
#endif

#include <string>

namespace Gadgetron{

  class GadgetronTimer
  {
  public:

    GadgetronTimer() : name_("GPUTimer"), timing_in_destruction_(true)
    {
        pre();
        start();
    }

    GadgetronTimer(bool timing) : name_("GPUTimer"), timing_in_destruction_(timing)
    {
        if ( timing_in_destruction_ )
        {
            pre();
            start();
        }
    }

    GadgetronTimer(const char* name, bool timing=true) : name_(name), timing_in_destruction_(timing) 
    {
        if ( timing_in_destruction_ )
        {
            pre();
            start();
        }
    }

    virtual ~GadgetronTimer() 
    {
        if ( timing_in_destruction_ )
        {
            post();
            stop();
        }
    }

    virtual void pre() {}
    virtual void post() {}

    virtual void start()
    {
#ifdef WIN32
        QueryPerformanceFrequency(&frequency_);
        QueryPerformanceCounter(&start_);
#else
        gettimeofday(&start_, NULL);
#endif
    }

    void start(const char* name)
    {
        name_ = name;
        start();
    }

    virtual double stop()
    {
        double time_in_us = 0.0;
#ifdef WIN32
        QueryPerformanceCounter(&end_);
        time_in_us = (end_.QuadPart * (1.0e6/ frequency_.QuadPart)) - start_.QuadPart * (1.0e6 / frequency_.QuadPart);
#else
        gettimeofday(&end_, NULL);
        time_in_us = ((end_.tv_sec * 1e6) + end_.tv_usec) - ((start_.tv_sec * 1e6) + start_.tv_usec);
#endif
	GDEBUG("%s:%f ms\n", name_.c_str(), time_in_us/1000.0);
        return time_in_us;
    }

    void set_timing_in_destruction(bool timing) { timing_in_destruction_ = timing; }

  protected:

#ifdef WIN32
    LARGE_INTEGER frequency_;
    LARGE_INTEGER start_;
    LARGE_INTEGER end_;
#else
    timeval start_;
    timeval end_;
#endif

    std::string name_;

    bool timing_in_destruction_;
  };
}

#endif //__GADGETRONTIMER_H
// ===== End: toolboxes/core/GadgetronTimer.h =====


using namespace Gadgetron;
using testing::Types;

template<typename Real>
class cuSDC_test : public ::testing::Test
{
    protected:
        virtual void SetUp()
        {
            GDEBUG_STREAM("=============================================================================================");
            char* ut_dir = ::getenv("GT_UNITTEST_DIRECTORY");
            if(ut_dir!=NULL)
            {
                gt_ut_folder_ = std::string(ut_dir);
            }
            else
                gt_ut_folder_.clear();

            GDEBUG_STREAM("=============================================================================================");

            if(!gt_ut_folder_.empty())
            {
                GDEBUG_STREAM("Unit Test for Gadgetron hoSDC");
                gt_ut_data_folder_ = gt_ut_folder_;
                gt_ut_res_folder_ = gt_ut_folder_;
                GDEBUG_STREAM("gt_ut_data_folder_ is " << gt_ut_data_folder_);
                GDEBUG_STREAM("gt_ut_res_folder_ is " << gt_ut_res_folder_);
            }

            this->timer_.set_timing_in_destruction(false);
        }

        std::string gt_ut_folder_;
        std::string gt_ut_data_folder_;
        std::string gt_ut_res_folder_;

        ImageIOAnalyze gt_io_;
        GadgetronTimer timer_;
};

typedef Types<float> realImplementations_cuSDC_test;

TYPED_TEST_SUITE(cuSDC_test, realImplementations_cuSDC_test);

TYPED_TEST(cuSDC_test, randomTestOne)
{
    typedef float T;

    if (this->gt_ut_folder_.empty())
    {
        GDEBUG_STREAM("Gadgetron unit test directory is not set ... ");
        return;
    }

    // Load test trajectory.
    hoNDArray<T> k_spiral;
    this->gt_io_.import_array(k_spiral, this->gt_ut_data_folder_ + "/spiral/k_spiral");
    std::stringstream k_spiral_stream;
    k_spiral.print(k_spiral_stream);
    GINFO(k_spiral_stream.str().c_str());
    T v = Gadgetron::nrm2(k_spiral); GDEBUG_STREAM("k_spiral = " << v);

    // Copy test trajectory to array of vector_td elements.
    size_t num_samples = k_spiral.get_number_of_elements() / 2;
    hoNDArray<vector_td<T, 2>> traj;
    traj.create(num_samples);
    for(size_t n = 0; n < num_samples; n++)
    {
        traj(n)[0] = k_spiral(n, 0);
        traj(n)[1] = k_spiral(n, 1);
    }

    // Run density estimation.
    vector_td<size_t, 2> dims;
    dims[0] = 256;
    dims[1] = 256;

    cuNDArray<vector_td<T, 2>> d_traj(traj);
    this->timer_.start("Estimate DCW...");
    cuNDArray<T> d_res = *estimate_dcw(d_traj, dims, T(3), 20, float(5.5));
    this->timer_.stop();
    hoNDArray<T> res = *d_res.to_host();
    std::stringstream res_stream;
    res.print(res_stream);
    GINFO(res_stream.str().c_str());

    // Save resulting weights.
    this->gt_io_.export_array(res, this->gt_ut_res_folder_ + "/spiral/res_weights");

    // Load reference weights.
    hoNDArray<T> ref;
    this->gt_io_.import_array(ref, this->gt_ut_data_folder_ + "/spiral/ref_weights");
    std::stringstream ref_stream;
    ref.print(ref_stream);
    GINFO(ref_stream.str().c_str());
    v = Gadgetron::nrm2(ref); GDEBUG_STREAM("ref = " << v);

    // Compare resulting weights against reference.
    hoNDArray<T> diff;
    Gadgetron::subtract(res, ref, diff);
    v = Gadgetron::nrm2(diff);
    T norm_ref = Gadgetron::nrm2(ref);
    EXPECT_LE(v/norm_ref, 0.00001);
}// ===== End: test/cuSDC_test.cpp =====


