template<class T> cuNDFFT<T>* cuNDFFT<T>::instance()
  				{
	if (!__instance)
		__instance = new cuNDFFT<T>;
	return __instance;
  				}

template<class T> cuNDFFT<T>* cuNDFFT<T>::__instance = NULL;

/* DPCT_ORIG template<class T> cufftType_t get_transform_type();*/
template <class T> dpct::fft::fft_type get_transform_type();
/* DPCT_ORIG template<> cufftType_t get_transform_type<float>() { return CUFFT_C2C; }*/
template <>
dpct::fft::fft_type get_transform_type<float>() {
  return dpct::fft::fft_type::complex_float_to_complex_float;
}
/* DPCT_ORIG template<> cufftType_t get_transform_type<double>() { return CUFFT_Z2Z; }*/
template <>
dpct::fft::fft_type get_transform_type<double>() {
  return dpct::fft::fft_type::complex_double_to_complex_double;
}

/* DPCT_ORIG template<class T> cufftResult_t cuNDA_FFT_execute( cufftHandle plan, cuNDArray< complext<T> > *in_out, int
 * direction );*/
template <class T> int cuNDA_FFT_execute(dpct::fft::fft_engine_ptr plan, cuNDArray<complext<T>>* in_out, int direction);

/* DPCT_ORIG template<> cufftResult_t cuNDA_FFT_execute<float>( cufftHandle plan, cuNDArray<float_complext> *in_out, int
 * direction ){*/
template <>
int cuNDA_FFT_execute<float>(dpct::fft::fft_engine_ptr plan, cuNDArray<float_complext>* in_out, int direction) {
/* DPCT_ORIG 	return cufftExecC2C(plan, (cuFloatComplex*)in_out->get_data_ptr(),
 * (cuFloatComplex*)in_out->get_data_ptr(), direction); }*/
        return DPCT_CHECK_ERROR((plan->compute<sycl::float2, sycl::float2>((sycl::float2*)in_out->get_data_ptr(), (sycl::float2*)in_out->get_data_ptr(), direction == 1 ? dpct::fft::fft_direction::backward : dpct::fft::fft_direction::forward))); }

/* DPCT_ORIG template<> cufftResult_t cuNDA_FFT_execute<double>( cufftHandle plan, cuNDArray<double_complext> *in_out,
 * int direction ){*/
template <>
int cuNDA_FFT_execute<double>(dpct::fft::fft_engine_ptr plan, cuNDArray<double_complext>* in_out, int direction) {
/* DPCT_ORIG 	return cufftExecZ2Z(plan, (cuDoubleComplex*)in_out->get_data_ptr(),
 * (cuDoubleComplex*)in_out->get_data_ptr(), direction); }*/
        return DPCT_CHECK_ERROR((plan->compute<sycl::double2, sycl::double2>((sycl::double2*)in_out->get_data_ptr(), (sycl::double2*)in_out->get_data_ptr(), direction == 1 ? dpct::fft::fft_direction::backward : dpct::fft::fft_direction::forward))); }

template <class T>
void cuNDFFT<T>::fft_int(cuNDArray<complext<T>>* input, std::vector<size_t>* dims_to_transform, int direction,
                         bool do_scale) try {
        std::vector<size_t> new_dim_order;
	std::vector<size_t> reverse_dim_order;
	std::vector<size_t> dim_count(input->get_number_of_dimensions(),0);

	size_t array_ndim = input->get_number_of_dimensions();
	std::vector<size_t> array_dims = input->get_dimensions();

	std::vector<size_t> dims = std::vector<size_t>(dims_to_transform->size(),0);
	for (size_t i = 0; i < dims_to_transform->size(); i++) {
		if ((*dims_to_transform)[i] >= array_ndim) {
			std::stringstream ss;
			ss << "cuNDFFT::fft Invalid dimensions specified for transform " << (*dims_to_transform)[i] << "max " << array_ndim;
			throw std::runtime_error(ss.str());;
		}
		if (dim_count[(*dims_to_transform)[i]] > 0) {
			throw std::runtime_error("cuNDFFT::fft Invalid dimensions (duplicates) specified for transform");;
		}
		dim_count[(*dims_to_transform)[i]]++;
		dims[dims_to_transform->size()-1-i] = array_dims[(*dims_to_transform)[i]];
	}

	new_dim_order = *dims_to_transform;
	for (size_t i = 0; i < array_ndim; i++) {
		if (!dim_count[i]) new_dim_order.push_back(i);
	}

	size_t ndim = dims.size();
	bool must_permute = false;

	{
		for (size_t i = 0; i < new_dim_order.size(); i++)
			must_permute |= (i != new_dim_order[i]);
	}

	//Check if we can use the fast FFT versions instead.
	if (!must_permute){
		switch (ndim){
		case 1:
			fft1_int(input,direction,do_scale);
			return;
			break;
		case 2:
			fft2_int(input,direction,do_scale);
			return;
			break;
		case 3:
			fft3_int(input,direction,do_scale);
			return;
			break;
		default:
			break;
		}
	}

	reverse_dim_order = std::vector<size_t>(array_ndim,0);
	for (size_t i = 0; i < array_ndim; i++) {
		reverse_dim_order[new_dim_order[i]] = i;
	}


	size_t batches = 0;
	size_t elements_in_ft = 1;
	for (size_t i = 0; i < dims.size(); i++)
		elements_in_ft *= dims[i];
	batches = input->get_number_of_elements() / elements_in_ft;

/* DPCT_ORIG 	cufftHandle plan;*/
        dpct::fft::fft_engine_ptr plan;
/* DPCT_ORIG 	cufftResult ftres;*/
        int ftres;

        std::vector<int> int_dims;
	for( unsigned int i=0; i<dims.size(); i++ )
		int_dims.push_back((int)dims[i]);

/* DPCT_ORIG 	ftres = cufftPlanMany(&plan,ndim,&int_dims[0], &int_dims[0], 1, elements_in_ft, &int_dims[0], 1,
 * elements_in_ft, get_transform_type<T>(), batches);*/
        ftres = DPCT_CHECK_ERROR(plan = dpct::fft::fft_engine::create(
                                     &dpct::get_in_order_queue(), ndim, &int_dims[0], &int_dims[0], 1, elements_in_ft,
                                     &int_dims[0], 1, elements_in_ft, get_transform_type<T>(), batches));
/* DPCT_ORIG 	if (ftres != CUFFT_SUCCESS) {*/
        if (ftres != 0) {
                std::stringstream ss;
		ss << "cuNDFFT FFT plan failed: " << ftres;
		throw std::runtime_error(ss.str());;
	}



	if (must_permute)
		*input = permute(*input,new_dim_order);


		for (size_t i =0; i < dims_to_transform->size(); i++)
			timeswitch(input,dims_to_transform->at(i));

/* DPCT_ORIG 	if( cuNDA_FFT_execute<T>( plan, input, direction ) != CUFFT_SUCCESS ) {*/
        if (cuNDA_FFT_execute<T>(plan, input, direction) != 0) {
                throw std::runtime_error("cuNDFFT FFT execute failed");;
	}

/* DPCT_ORIG 	ftres = cufftDestroy( plan );*/
        ftres = DPCT_CHECK_ERROR(dpct::fft::fft_engine::destroy(plan));
/* DPCT_ORIG 	if (ftres != CUFFT_SUCCESS) {*/
        if (ftres != 0) {
                std::stringstream ss;
		ss << "cuNDFFT FFT plan destroy failed: " << ftres;
		throw std::runtime_error(ss.str());;
	}

		for (size_t i =0; i < dims_to_transform->size(); i++)
			timeswitch(input,dims_to_transform->at(i));

	if (do_scale) {
		*input *= 1/std::sqrt(T(elements_in_ft));
	}

	if (must_permute)
		*input = permute(*input,reverse_dim_order);
}
catch (sycl::exception const& exc) {
  std::cerr << exc.what() << "Exception caught at file:" << __FILE__ << ", line:" << __LINE__ << std::endl;
  std::exit(1);
}

template <class T> void cuNDFFT<T>::fft1_int(cuNDArray<complext<T>>* input, int direction, bool do_scale) try {
/* DPCT_ORIG 	cufftHandle plan;*/
        dpct::fft::fft_engine_ptr plan;
/* DPCT_ORIG 	cufftResult ftres;*/
        int ftres;

        std::vector<int> int_dims {int(input->get_size(0))};
	int elements_in_ft = input->get_size(0);
	int batches = input->get_number_of_elements()/elements_in_ft;
/* DPCT_ORIG 	ftres = cufftPlanMany(&plan,1,&int_dims[0], &int_dims[0], 1, elements_in_ft, &int_dims[0], 1,
 * elements_in_ft, get_transform_type<T>(), batches);*/
        ftres = DPCT_CHECK_ERROR(plan = dpct::fft::fft_engine::create(
                                     &dpct::get_in_order_queue(), 1, &int_dims[0], &int_dims[0], 1, elements_in_ft,
                                     &int_dims[0], 1, elements_in_ft, get_transform_type<T>(), batches));
/* DPCT_ORIG 	if (ftres != CUFFT_SUCCESS) {*/
        if (ftres != 0) {
                std::stringstream ss;
		ss << "cuNDFFT FFT plan failed: " << ftres;
		throw std::runtime_error(ss.str());;
	}

		timeswitch1D(input);

/* DPCT_ORIG 	if( cuNDA_FFT_execute<T>( plan, input, direction ) != CUFFT_SUCCESS ) {*/
        if (cuNDA_FFT_execute<T>(plan, input, direction) != 0) {
                throw std::runtime_error("cuNDFFT FFT execute failed");;
	}

/* DPCT_ORIG 	ftres = cufftDestroy( plan );*/
        ftres = DPCT_CHECK_ERROR(dpct::fft::fft_engine::destroy(plan));
/* DPCT_ORIG 	if (ftres != CUFFT_SUCCESS) {*/
        if (ftres != 0) {
                std::stringstream ss;
		ss << "cuNDFFT FFT plan destroy failed: " << ftres;
		throw std::runtime_error(ss.str());;
	}


		timeswitch1D(input);
	if (do_scale) {
		*input *= 1/std::sqrt(T(elements_in_ft));
	}
}
catch (sycl::exception const& exc) {
  std::cerr << exc.what() << "Exception caught at file:" << __FILE__ << ", line:" << __LINE__ << std::endl;
  std::exit(1);
}

